window.BB_DEFAULTS={"tel":"+37120762447","news":[{"id":"n1","date":"2026-10-05","cat":"shop","title":{"lv":"Kluba ekipējuma līnija ir klāt","ru":"Линейка клубной экипировки уже здесь","en":"The club equipment line has arrived"},"text":{"lv":"Krīts, kijas, bumbu komplekts un piederumi ar Baltijas Biljards Nr.1 zīmi tagad pieejami klubā. Apskati visu veikala sadaļā.","ru":"Мел, кии, комплект шаров и аксессуары с символикой Baltijas Biljards Nr.1 теперь доступны в клубе. Смотрите всё в разделе «Магазин».","en":"Chalk, cues, a ball set and accessories with the Baltijas Biljards Nr.1 mark are now available at the club. See everything in the shop section."},"img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/balls.webp"},{"id":"n2","date":"2026-09-28","cat":"tournaments","title":{"lv":"Rudens sezonā atgriežas Saturday Tournament","ru":"В осеннем сезоне возвращается Saturday Tournament","en":"Saturday Tournament returns for the autumn season"},"text":{"lv":"Atklātie sestdienas turnīri atsākas. Piedalīties var spēlētāji ar jebkuru pieredzi, reģistrācija — TournamentService.","ru":"Открытые субботние турниры возобновляются. Участвовать могут игроки с любым опытом, регистрация — на TournamentService.","en":"The open Saturday tournaments are back. Players of any experience can take part; registration is on TournamentService."},"img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-3.jpg"},{"id":"n3","date":"2026-09-15","cat":"school","title":{"lv":"Biljarda skola uzņem jaunas grupas","ru":"Школа бильярда набирает новые группы","en":"The billiards school is enrolling new groups"},"text":{"lv":"Nodarbības bērniem un pieaugušajiem sākas no pašiem pamatiem: stāja, tilts, sitiens. Piesakies pa e-pastu.","ru":"Занятия для детей и взрослых начинаются с самых основ: стойка, мост, удар. Записывайтесь по e-mail.","en":"Lessons for children and adults start from the very basics: stance, bridge, stroke. Sign up by email."},"img":"https://baltijas-biljards-nr1.vercel.app/assets/img/hero-1.jpg"},{"id":"n4","date":"2026-09-01","cat":"club","title":{"lv":"Jauna vadmala uz piramīdas galdiem","ru":"Новое сукно на столах для пирамиды","en":"New cloth on the pyramid tables"},"text":{"lv":"Pirms sezonas esam nomainījuši vadmalu uz piramīdas galdiem — bumba ripo ātrāk un vienmērīgāk.","ru":"Перед сезоном мы заменили сукно на столах для пирамиды — шар катится быстрее и ровнее.","en":"Before the season we replaced the cloth on the pyramid tables — the ball now rolls faster and more evenly."},"img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-4.jpg"},{"id":"n5","date":"2026-08-20","cat":"club","title":{"lv":"Vakars ar kolēģiem pie biljarda galda","ru":"Вечер с коллегами за бильярдным столом","en":"An evening with colleagues at the billiard table"},"text":{"lv":"Rezervē vairākus galdus blakus uzņēmuma vakaram vai draugu kompānijai. Zvani, un atradīsim laiku.","ru":"Забронируйте несколько столов рядом для корпоратива или компании друзей. Звоните — найдём время.","en":"Reserve several tables side by side for a company evening or a group of friends. Call us and we will find a time."},"img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-1.jpg"}],"tournaments":[{"id":"tr1","date":"","time":"","title":{"lv":"Latvijas čempionāti","ru":"Чемпионаты Латвии","en":"Latvian championships"},"info":{"lv":"Latvijas mēroga piramīdas sacensības notiek arī mūsu zālē.","ru":"Соревнования по пирамиде национального уровня проходят и в нашем зале.","en":"Latvian-level pyramid competitions are also held in our hall."},"link":""},{"id":"tr2","date":"","time":"","title":{"lv":"Saturday Tournament","ru":"Saturday Tournament","en":"Saturday Tournament"},"info":{"lv":"Atklāts turnīrs: piedalīties var gan pieredzējuši spēlētāji, gan tie, kas tikai sāk.","ru":"Открытый турнир: участвовать могут и опытные игроки, и те, кто только начинает.","en":"An open tournament: both experienced players and complete beginners can take part."},"link":""},{"id":"tr3","date":"","time":"","title":{"lv":"Kluba kausi","ru":"Кубки клуба","en":"Club cups"},"info":{"lv":"Par īpašajiem turnīriem un kausiem paziņojam atsevišķi — seko kalendāram.","ru":"Об особых турнирах и кубках сообщаем отдельно — следите за календарём.","en":"We announce special tournaments and cups separately — keep an eye on the calendar."},"link":""}],"rules":[{"id":"disc","title":{"lv":"Disciplīnas","ru":"Дисциплины","en":"Disciplines"},"body":{"lv":"Mūsu klubā spēlē trīs galvenos biljarda veidus:\n- Krievu biljards (piramīda): brīvā, kombinētā, moskviešu un dinamiskā piramīda.\n- Pūls: 8 bumbas, 9 bumbas, 10 bumbas un 14.1 nepārtrauktā spēle.\n- Snukers: klasiskais snukers ar 15 sarkanajām un 6 krāsainajām bumbām.\nKonkrētā turnīra disciplīna vienmēr norādīta turnīra nolikumā.","ru":"В клубе играют в три основных вида бильярда:\n- Русский бильярд (пирамида): свободная, комбинированная, московская и динамичная пирамида.\n- Пул: 8 шаров, 9 шаров, 10 шаров и 14.1 «в одну партию».\n- Снукер: классический снукер с 15 красными и 6 цветными шарами.\nДисциплина конкретного турнира всегда указана в положении о турнире.","en":"The club offers three main kinds of billiards:\n- Russian billiards (pyramid): free, combined, Moscow and dynamic pyramid.\n- Pool: 8-ball, 9-ball, 10-ball and 14.1 continuous.\n- Snooker: classic snooker with 15 reds and 6 colours.\nThe discipline of a given tournament is always stated in its regulations."},"link":""},{"id":"pyr","title":{"lv":"Piramīdas noteikumi","ru":"Правила пирамиды","en":"Pyramid rules"},"body":{"lv":"Īss atgādinājums. Oficiālie noteikumi — pie tiesneša vai klubā.\n- Spēlē 12 pēdu galdā ar 15 mērķa bumbām un bitu, bumbas diametrs 68 mm.\n- Bumbas saliek trijstūrī, spēle sākas ar sitienu pa piramīdu.\n- Uzvar tas, kurš pirmais iesit noteikto bumbu skaitu (parasti 8).\n- Kļūda (fouls): bita iešana kabatā, bumba ārpus galda vai nepareizs sitiens — gājiens pāriet pretiniekam.\n- Precīzus noteikumus nosaka izvēlētā disciplīna (brīvā, kombinētā, moskviešu, dinamiskā).","ru":"Краткая памятка. Официальный текст правил — у судьи или в клубе.\n- Играют на столе 12 футов, 15 прицельных шаров и биток, диаметр шаров 68 мм.\n- Шары ставятся треугольником, партия начинается с разбоя пирамиды.\n- Побеждает тот, кто первым забьёт нужное число шаров (обычно 8).\n- Фол: биток в лузе, шар за бортом или неправильный удар — ход переходит сопернику.\n- Точные правила зависят от выбранной дисциплины (свободная, комбинированная, московская, динамичная).","en":"A short reminder. The official rules are available from the referee or at the club.\n- Played on a 12 ft table with 15 object balls and a cue ball, ball diameter 68 mm.\n- Balls are racked in a triangle and the game starts with a break.\n- The winner is the first to pocket the required number of balls (usually 8).\n- Foul: cue ball pocketed, ball off the table or a wrong stroke — the turn passes to the opponent.\n- Exact rules depend on the chosen discipline (free, combined, Moscow, dynamic)."},"link":""},{"id":"pool","title":{"lv":"Pūla noteikumi","ru":"Правила пула","en":"Pool rules"},"body":{"lv":"Īss atgādinājums. Oficiālie noteikumi — pie tiesneša vai klubā.\n- 8 bumbas: 15 bumbas — vesels (1–7) un svītrains (9–15) komplekts un melnā 8. Jāiesit sava grupa, tad 8. bumba.\n- 9 bumbas: bumbas 1–9, vienmēr jātrāpa pa mazāko numuru; uzvar tas, kurš likumīgi iesit 9. bumbu.\n- 10 bumbas: kā 9 bumbas, bet kabata jānosauc.\n- 14.1: katra iesistā bumba ir 1 punkts, spēlē līdz noteiktam punktu skaitam.\n- Pēc kļūdas pretinieks drīkst novietot bitu jebkur uz galda.","ru":"Краткая памятка. Официальный текст правил — у судьи или в клубе.\n- 8 шаров: 15 шаров — «цельные» (1–7), «полосатые» (9–15) и чёрный 8. Нужно забить свою группу, затем 8-й шар.\n- 9 шаров: шары 1–9, всегда нужно попасть по наименьшему номеру; побеждает тот, кто легально забил 9-й.\n- 10 шаров: как 9 шаров, но лузу нужно называть.\n- 14.1: каждый забитый шар — 1 очко, игра до заранее оговорённого числа очков.\n- После фола соперник ставит биток в любое место стола.","en":"A short reminder. The official rules are available from the referee or at the club.\n- 8-ball: 15 balls — solids (1–7), stripes (9–15) and the black 8. Pocket your group, then the 8.\n- 9-ball: balls 1–9, you must always hit the lowest number first; whoever legally pockets the 9 wins.\n- 10-ball: like 9-ball, but the pocket must be called.\n- 14.1: every pocketed ball is 1 point, the game is played to an agreed number of points.\n- After a foul the opponent places the cue ball anywhere on the table."},"link":""},{"id":"snooker","title":{"lv":"Snukera noteikumi","ru":"Правила снукера","en":"Snooker rules"},"body":{"lv":"Īss atgādinājums. Oficiālie noteikumi — pie tiesneša vai klubā.\n- 22 bumbas: 15 sarkanās (1 punkts), dzeltenā 2, zaļā 3, brūnā 4, zilā 5, rozā 6, melnā 7 un baltā bita bumba.\n- Gājiens: vispirms sarkanā, tad jebkura krāsainā (tā tiek izcelta atpakaļ), un tā tālāk.\n- Kad sarkanās beigušās, krāsainās iesit augošā secībā no dzeltenās līdz melnajai.\n- Kļūda (fouls): vismaz 4 punkti pretiniekam.\n- Freimu uzvar tas, kuram vairāk punktu.","ru":"Краткая памятка. Официальный текст правил — у судьи или в клубе.\n- 22 шара: 15 красных (1 очко), жёлтый 2, зелёный 3, коричневый 4, синий 5, розовый 6, чёрный 7 и белый биток.\n- Очередность: сначала красный, затем любой цветной (он возвращается на стол), и так далее.\n- Когда красные закончились, цветные забиваются по возрастанию — от жёлтого до чёрного.\n- Фол: минимум 4 очка в пользу соперника.\n- Фрейм выигрывает тот, у кого больше очков.","en":"A short reminder. The official rules are available from the referee or at the club.\n- 22 balls: 15 reds (1 point), yellow 2, green 3, brown 4, blue 5, pink 6, black 7 and the white cue ball.\n- Order of play: a red first, then any colour (it is re-spotted), and so on.\n- When the reds are gone, the colours are pocketed in ascending order, yellow to black.\n- Foul: at least 4 points to the opponent.\n- The frame is won by the player with more points."},"link":""},{"id":"ekp","title":{"lv":"EKP noteikumi","ru":"Правила ЕКП","en":"EKP rules"},"body":{"lv":"","ru":"","en":""},"link":""},{"id":"mkp","title":{"lv":"MKP noteikumi","ru":"Правила МКП","en":"MKP rules"},"body":{"lv":"","ru":"","en":""},"link":""}],"slots":[{"key":"logo","label":"Логотип — главная страница","img":"assets/img/logo.jpg"},{"key":"home.hero","label":"Главная — большое фото","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/hero-1.jpg"},{"key":"home.pyramid","label":"Главная — карточка «Пирамида»","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-4.jpg"},{"key":"home.pool","label":"Главная — карточка «Пул»","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-2.jpg"},{"key":"home.hall","label":"Главная — плитка «Зал»","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-1.jpg"},{"key":"home.tournaments","label":"Главная — плитка «Турниры»","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-3.jpg"},{"key":"home.school","label":"Главная — плитка «Школа»","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-6.jpg"},{"key":"home.shop","label":"Главная — плитка «Магазин»","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/cue-pyramid.webp"},{"key":"tables.hero","label":"Столы — большое фото","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-4.jpg"},{"key":"tables.tt","label":"Столы — настольный теннис","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-5.jpg"},{"key":"hall.1","label":"Зал — фото 1 (большое)","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-1.jpg"},{"key":"hall.2","label":"Зал — фото 2","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-2.jpg"},{"key":"hall.3","label":"Зал — фото 3","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-3.jpg"},{"key":"hall.4","label":"Зал — фото 4 (высокое)","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-4.jpg"},{"key":"hall.5","label":"Зал — фото 5","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-5.jpg"},{"key":"hall.6","label":"Зал — фото 6","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-6.jpg"},{"key":"tournaments.hero","label":"Турниры — большое фото","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-3.jpg"},{"key":"school.hero","label":"Школа — большое фото","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/hero-1.jpg"},{"key":"news.1","label":"Новости — новость 1 (экипировка)","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/balls.webp"},{"key":"news.2","label":"Новости — новость 2 (Saturday Tournament)","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-3.jpg"},{"key":"news.3","label":"Новости — новость 3 (школа)","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/hero-1.jpg"},{"key":"news.4","label":"Новости — новость 4 (новое сукно)","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-4.jpg"},{"key":"news.5","label":"Новости — новость 5 (вечер с коллегами)","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/club-1.jpg"}],"products":[{"id":"p1","name":{"lv":"Krīts Nr.1","ru":"Мел Nr.1","en":"Chalk Nr.1"},"desc":{"lv":"Smalkgraudains krīts drošai uzlīmes saķerei ar bumbu.","ru":"Мелкозернистый мел для надёжного сцепления наклейки с шаром.","en":"Fine-grain chalk for a secure grip between the tip and the ball."},"price":"","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/chalk.webp"},{"id":"p2","name":{"lv":"Kija piramīdai","ru":"Кий для пирамиды","en":"Pyramid cue"},"desc":{"lv":"Divdaļīga kija krievu biljardam ar kluba emblēmu.","ru":"Двухсоставной кий для русского бильярда с эмблемой клуба.","en":"Two-piece cue for Russian billiards with the club emblem."},"price":"","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/cue-pyramid.webp"},{"id":"p3","name":{"lv":"Kija pūlam","ru":"Кий для пула","en":"Pool cue"},"desc":{"lv":"Viegla un precīza kija pūlam ar ādas tinumu.","ru":"Лёгкий и точный кий для пула с кожаной обмоткой.","en":"A light, accurate pool cue with a leather wrap."},"price":"","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/cue-pool.webp"},{"id":"p4","name":{"lv":"Piramīdas bumbu komplekts","ru":"Комплект шаров для пирамиды","en":"Pyramid ball set"},"desc":{"lv":"15 baltas bumbas un sitamā bumba, 68 mm, koka kastē.","ru":"15 белых шаров и биток, 68 мм, в деревянной коробке.","en":"15 white balls and a cue ball, 68 mm, in a wooden box."},"price":"","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/balls.webp"},{"id":"p5","name":{"lv":"Uzlīmju komplekts","ru":"Комплект наклеек","en":"Tip set"},"desc":{"lv":"Daudzslāņu ādas uzlīmes precīzai kontrolei.","ru":"Многослойные кожаные наклейки для точного контроля.","en":"Multi-layer leather tips for precise control."},"price":"","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/tips.webp"},{"id":"p6","name":{"lv":"Cimds","ru":"Перчатка","en":"Glove"},"desc":{"lv":"Trīs pirkstu cimds vienmērīgam kijas slīdējumam.","ru":"Перчатка на три пальца для ровного скольжения кия.","en":"A three-finger glove for a smooth cue glide."},"price":"","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/glove.webp"},{"id":"p7","name":{"lv":"Kijas tubuss","ru":"Тубус для кия","en":"Cue case"},"desc":{"lv":"Ciets futrālis ar ādas apdari divdaļīgai kijai.","ru":"Жёсткий футляр с кожаной отделкой для двухсоставного кия.","en":"A hard case with leather trim for a two-piece cue."},"price":"","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/case.webp"},{"id":"p8","name":{"lv":"Trijstūris","ru":"Треугольник","en":"Triangle rack"},"desc":{"lv":"Koka trijstūris ar misiņa plāksnīti piramīdas salikšanai.","ru":"Деревянный треугольник с латунной пластиной для сборки пирамиды.","en":"A wooden triangle with a brass plate for racking the pyramid."},"price":"","img":"https://baltijas-biljards-nr1.vercel.app/assets/img/shop/rack.webp"}],"prices":{"groups":[{"id":"g-pyramid","vip":false,"title":{"lv":"Piramīda","ru":"Пирамида","en":"Pyramid"},"note":{"lv":"9 galdi","ru":"9 столов","en":"9 tables"},"rows":[{"id":"g-pyramid-r1","label":{"lv":"1 stunda","ru":"1 час","en":"1 hour"},"price":"","unit":{"lv":"","ru":"","en":""}}]},{"id":"g-pool","vip":false,"title":{"lv":"Pūls","ru":"Пул","en":"Pool"},"note":{"lv":"6 galdi","ru":"6 столов","en":"6 tables"},"rows":[{"id":"g-pool-r1","label":{"lv":"1 stunda","ru":"1 час","en":"1 hour"},"price":"","unit":{"lv":"","ru":"","en":""}}]},{"id":"g-vip","vip":true,"title":{"lv":"VIP zāle","ru":"VIP зал","en":"VIP room"},"note":{"lv":"1 galds VIP zālē","ru":"1 стол в VIP зале","en":"1 table in the VIP room"},"rows":[{"id":"g-vip-r1","label":{"lv":"1 stunda","ru":"1 час","en":"1 hour"},"price":"","unit":{"lv":"","ru":"","en":""}}]}]}};
